import numpy as np
from scipy.optimize import least_squares
d=df[(df.speed==0)&(df.height==10)&(df.air_density==1.2)].copy()
def sim(k,h=10,g=9.81,n=4000):
    # quadratic drag, vertical: dv/dt=g-k v^2 ; x(t)
    # analytic: v=sqrt(g/k) tanh(t sqrt(gk)); fall dist=(1/k)ln cosh(t sqrt(gk))
    a=np.sqrt(g*k); T=np.arccosh(np.exp(k*h))/a; v=np.sqrt(g/k)*np.tanh(a*T); return T,v
def pred(p,d):
    c={'sphere':p[0],'cube':p[1],'cylinder':p[2]}
    k=np.array([c[s] for s in d['shape']])*d.radius**p[3]/d.mass**p[4]
    T,v=sim(np.maximum(k,1e-9)); return T,v
def res(p):
    T,v=pred(p,d); return np.r_[(T-d.flight_time)/0.01,(v-d.impact_speed)/(0.01*d.impact_speed)]
r=least_squares(res,[1,1.5,1.2,2,1]);print(r.x,np.sqrt(np.mean(r.fun**2)))
T,v=pred(r.x,d);d['rT']=d.flight_time-T
for c in ['reflectance','temperature','stripes','hardness','batch']:print(c,np.corrcoef(d[c],d.rT)[0,1])

